head.script:
/* =========================================================================
 * WAEA-866 검증용 _fix 샘플
 * 핫픽스: 2026_0520_hotfix_WAEA_866.js (기준 REL_6_0_0_1438B_20260120_113942)
 *
 * 목적: $p.ajax / WebSquare.net.ajax 의 mode=synchronous(및 mode 생략) 요청에서도
 *       withCredentials 설정값이 실제 XMLHttpRequest.send 직전에 정상 반영되는지 확인.
 *
 * ※ WAEA-860(submission)과는 호출 경로가 다른 별도 이슈이므로 ajax 경로를 직접 호출함.
 *
 * 확인 방법: 각 버튼 클릭 후 콘솔의 "[XHR send] withCredentials = ..." 로그 확인.
 * ========================================================================= */

// --- (1) XHR 가로채기: send 직전 withCredentials / 동기여부 / url 출력 ---
(function () {
    if (XMLHttpRequest.prototype.__waea866Patched) { return; }
    XMLHttpRequest.prototype.__waea866Patched = true;

    var _open = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function (method, url, async) {
        this.__url = url;
        this.__async = (async !== false); // 미지정 시 기본 true
        return _open.apply(this, arguments);
    };

    var _send = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.send = function (body) {
        console.log(
            "[XHR send] withCredentials =", this.withCredentials,
            "| mode =", (this.__async ? "asynchronous" : "synchronous"),
            "| url =", this.__url
        );
        return _send.apply(this, arguments);
    };
})();

// action 으로 사용할 리소스 (test2 폴더에 존재)
var ACTION_URL = "ajax_withCredentials_WAEA-866_(WSQ-6326.json";

// --- (2) 공통 호출 함수 ---
// fn: "p" = $p.ajax / "net" = WebSquare.net.ajax
scwin.callAjax = function (label, fn, opt) {
    var base = {
        url: ACTION_URL,
        action: ACTION_URL,   // 엔진 버전별 옵션명 호환용
        contentType: "application/json",
        dataType: "json",
        success: function () {},
        error: function () {}
    };
    for (var k in opt) { base[k] = opt[k]; }

    console.log("==== [" + label + "] 호출 / 설정값:",
        "fn =", (fn === "p" ? "$p.ajax" : "WebSquare.net.ajax"),
        ", mode =", (base.hasOwnProperty("mode") ? base.mode : "(미지정)"),
        ", withCredentials =", (base.hasOwnProperty("withCredentials") ? base.withCredentials : "(미지정)"));

    if (fn === "p") {
        $p.ajax(base);
    } else {
        WebSquare.net.ajax(base);
    }
};

// --- (3) 검증 케이스 ---
// 1) $p.ajax 동기 + true            → 기대: 핫픽스 후 true (전 false=버그)
scwin.btn1 = function () { scwin.callAjax("1.$p.ajax sync+true", "p",   { mode: "synchronous",  withCredentials: true }); };
// 2) WebSquare.net.ajax 동기 + true → 기대: true
scwin.btn2 = function () { scwin.callAjax("2.net.ajax sync+true", "net", { mode: "synchronous",  withCredentials: true }); };
// 3) $p.ajax 비동기 + true          → 기대: true (하위호환)
scwin.btn3 = function () { scwin.callAjax("3.$p.ajax async+true", "p",   { mode: "asynchronous", withCredentials: true }); };
// 4) $p.ajax mode 생략 + true       → 기대: true (이번 핫픽스의 추가 보정 경로)
scwin.btn4 = function () { scwin.callAjax("4.$p.ajax (mode생략)+true", "p", { withCredentials: true }); };
// 5) $p.ajax 동기 + false           → 기대: false (기본값 유지)
scwin.btn5 = function () { scwin.callAjax("5.$p.ajax sync+false", "p",  { mode: "synchronous",  withCredentials: false }); };
// 6) $p.ajax 동기 + 미지정          → 기대: false (기본값 유지)
scwin.btn6 = function () { scwin.callAjax("6.$p.ajax sync+미지정", "p",  { mode: "synchronous" }); };
// 전체 순차 실행
scwin.btnAll = function () { scwin.btn1(); scwin.btn2(); scwin.btn3(); scwin.btn4(); scwin.btn5(); scwin.btn6(); };

scwin.onpageload = function () {
    console.log("WAEA-866 _fix 로드 완료. 버튼을 눌러 case별 withCredentials 값을 확인하세요.");
};
scwin.onpageunload = function () {};
